// Macro to apply light configuration to a token in Foundry VTT
const token = canvas.tokens.controlled[0];
if (!token) {
  ui.notifications.warn("No token selected!");
  return;
}

const lightConfig = {
  "alpha": 0.5,
  "angle": 360,
  "bright": 5,
  "coloration": 7,
  "dim": 5,
  "attenuation": 0.5,
  "luminosity": 0.75,
  "saturation": 0.75,
  "contrast": 0.65,
  "shadows": 0,
  "animation": {
    "type": "fairy",
    "speed": 5,
    "intensity": 5,
    "reverse": false
  },
  "darkness": {
    "min": 0,
    "max": 1
  },
  "color": "#ffffff",
  "negative": false,
  "priority": 0
};

token.document.update({ light: lightConfig });
ui.notifications.info("Light configuration applied!");
